// Local alias shapes. Each returns {imports, pre (module level), decl (the alias declaration), truth, contract?}.
'use strict';
const { FORMS, ty } = require('./variants-common.cjs');

const NS = `import * as N from './callee';`;
const LOCAL_SHAPES = {
  'ident': (c) => ({ imports: `import { ${c.T} as imp } from './callee';`, decl: `const ${c.L} = imp;`, truth: 'T' }),
  'ns-member': (c) => ({ imports: NS, decl: `const ${c.L} = N.${c.T};`, truth: 'T' }),
  'ns-destructure': (c) => ({
    imports: NS,
    decl: c.L === c.T ? `const { ${c.T} } = N;` : `const { ${c.T}: ${c.L} } = N;`,
    truth: 'T',
  }),
  'obj-member': (c) => ({
    imports: `import { ${c.T} as imp } from './callee';`,
    decl: `const o = { ${c.T}: imp }; const ${c.L} = o.${c.T};`,
    truth: 'T',
  }),
  'chain2': (c) => ({ imports: NS, decl: `const a0 = N.${c.T}; const ${c.L} = a0;`, truth: 'T' }),
  'let-stable': (c) => ({ imports: NS, decl: `let ${c.L} = N.${c.T};`, truth: 'T' }),
  'let-reassigned': (c) => ({
    imports: NS,
    decl: `let ${c.L}${ty(c.lang, ': any')} = N.${c.T}; if (c) { ${c.L} = N.${c.ALT}; }`,
    truth: 'SET',
    scopes: ['fn', 'outer'],
  }),
  'var': (c) => ({ imports: NS, decl: `var ${c.L} = N.${c.T};`, truth: 'T' }),
  'conditional': (c) => ({ imports: NS, decl: `const ${c.L} = c ? N.${c.T} : N.${c.ALT};`, truth: 'SET', scopes: ['fn', 'outer'] }),
  'wrapper-call': (c) => ({
    imports: `import { ${c.T} as imp } from './callee';`,
    pre: `function wrap(fn${ty(c.lang, ': any')})${ty(c.lang, ': any')} { return fn; }`,
    decl: `const ${c.L} = wrap(imp);`,
    truth: 'T',
    contract: 'wrapper call result (memo, useCallback, forwardRef): is the wrapped callable the callee?',
  }),
  'bind': (c) => ({
    imports: NS,
    decl: `const ${c.L} = N.${c.T}.bind(null);`,
    truth: 'T',
    forms: ['call'],
    contract: '.bind result',
  }),
  'array-destructure': (c) => ({ imports: `import { ${c.T} as imp } from './callee';`, decl: `const [${c.L}] = [imp];`, truth: 'T' }),
  'default-destructure': (c) => ({
    imports: `import { ${c.T} as imp } from './callee';`,
    decl: `const { cb: ${c.L} = imp } = opts;`,
    truth: 'MAY',
    scopes: ['fn', 'outer'],
  }),
  'fallback-or': (c) => ({
    imports: `import { ${c.T} as imp } from './callee';`,
    decl: `const ${c.L} = opts.cb || imp;`,
    truth: 'MAY',
    scopes: ['fn', 'outer'],
  }),
  'ns-member-paren': (c) => ({ imports: NS, decl: `const ${c.L} = (N.${c.T});`, truth: 'T' }),
  'ns-member-as': (c) => ({ imports: NS, decl: `const ${c.L} = N.${c.T} as typeof N.${c.T};`, truth: 'T', langs: ['ts'] }),
  'ns-member-nonnull': (c) => ({ imports: NS, decl: `const ${c.L} = N.${c.T}!;`, truth: 'T', langs: ['ts'] }),
  'block-shadow': (c) => ({
    imports: NS,
    decl: `const ${c.L} = N.${c.ALT};\n  if (c) {\n    const ${c.L} = N.${c.T};\n    ${FORMS[c.form].site(c.L)}\n  }`,
    noSite: true,
    truth: 'T',
    scopes: ['fn'],
    forms: ['call'],
  }),
  'react-memo': (c) => ({
    imports: `import { memo } from 'react';\nimport { ${c.T} as imp } from './callee';`,
    decl: `const ${c.L} = memo(imp);`,
    // memo() returns a component object: rendering it reaches the wrapped function, calling it throws
    truth: c.form === 'jsx' ? 'T' : 'NONE',
    forms: ['call', 'jsx'],
    scopes: ['module', 'fn'],
    contract: c.form === 'jsx' ? 'library wrapper (memo, forwardRef, observer): is the wrapped callable the callee?' : null,
  }),
  'react-usecallback-ident': (c) => ({
    imports: `import { useCallback } from 'react';\nimport { ${c.T} as imp } from './callee';`,
    decl: `const ${c.L} = useCallback(imp, []);`,
    truth: 'T',
    forms: ['call'],
    scopes: ['fn'],
    contract: 'library wrapper (useCallback, useMemo): is the wrapped callable the callee?',
  }),
  'react-usecallback-inline': (c) => ({
    imports: `import { useCallback } from 'react';`,
    decl: `const ${c.L} = useCallback((x${ty(c.lang, ': any')}) => x, []); // ANON`,
    truth: 'ANON',
    forms: ['call'],
    scopes: ['fn'],
    contract: 'library wrapper around an inline callable',
  }),
  'react-usestate-setter': (c) => ({
    imports: `import { useState } from 'react';`,
    decl: `const [value, ${c.L}] = useState(0);`,
    truth: 'NONE',
    forms: ['call'],
    namings: ['trap', 'fresh'],
    scopes: ['fn', 'outer'],
  }),
  'react-usecontext-destructure': (c) => ({
    imports: `import { createContext, useContext } from 'react';\nimport { ${c.T} as imp } from './callee';`,
    pre: `export const Ctx = createContext({ ${c.T}: imp });`,
    decl: c.L === c.T ? `const { ${c.T} } = useContext(Ctx);` : `const { ${c.T}: ${c.L} } = useContext(Ctx);`,
    truth: 'MAY',
    forms: ['call'],
    scopes: ['fn', 'outer'],
    contract: 'context value: the default is visible, providers may not be',
  }),
  'custom-hook-array-result': (c) => ({
    imports: `import { ${c.T} as imp } from './callee';`,
    pre: `function useThing() { return [1, imp]${ty(c.lang, ' as const')}; }`,
    decl: `const [value, ${c.L}] = useThing();`,
    truth: 'T',
    forms: ['call'],
    scopes: ['fn', 'outer'],
    contract: 'value returned by a same-file function (hook result)',
  }),
  'styled-template': (c) => ({
    imports: `import styled from 'styled-components';`,
    decl: `const ${c.L} = styled.div\`color: red;\`;`,
    truth: 'NONE',
    forms: ['jsx'],
    namings: ['trap', 'fresh'],
    scopes: ['module', 'fn'],
  }),
  'react-lazy': (c) => ({
    imports: `import { lazy } from 'react';`,
    decl: `const ${c.L} = lazy(() => import('./dflt'));`,
    truth: 'DFLT',
    forms: ['jsx'],
    scopes: ['module'],
    contract: 'lazy(() => import(...)): is the default export the callee?',
  }),
  'element-member': (c) => ({
    imports: `import { ${c.T} as imp } from './callee';`,
    decl: `const table = [imp]; const ${c.L} = table[0];`,
    truth: 'T',
    forms: ['call'],
    contract: 'element access into a local array literal',
  }),
  'deep-member': (c) => ({
    imports: `import { ${c.T} as imp } from './callee';`,
    decl: `const o = { inner: { ${c.T}: imp } }; const ${c.L} = o.inner.${c.T};`,
    truth: 'T',
    forms: ['call'],
  }),
  'declared-then-assigned': (c) => ({
    imports: NS,
    decl: `let ${c.L}${ty(c.lang, ': any')}; ${c.L} = N.${c.T};`,
    truth: 'T',
    forms: ['call'],
    scopes: ['fn', 'outer'],
    contract: 'declared without a value, assigned once',
  }),
  'for-of-element': (c) => ({
    imports: `import { ${c.T} as imp } from './callee';`,
    decl: `for (const ${c.L} of [imp]) {\n    ${FORMS[c.form].site(c.L)}\n  }`,
    noSite: true,
    truth: 'T',
    forms: ['call'],
    scopes: ['fn'],
    contract: 'loop variable over a local array literal',
  }),
  'object-param-destructure': (c) => ({
    imports: '',
    decl: `const { ${c.L} } = opts;`,
    truth: 'UNKNOWN',
    forms: ['call'],
    namings: ['trap', 'fresh'],
    scopes: ['fn', 'outer'],
  }),
  'local-arrow': (c) => ({
    imports: '',
    decl: c.form === 'new' ? `class ${c.L} { constructor(x${ty(c.lang, ': number')}) {} }` : `const ${c.L} = (x${ty(c.lang, ': any')}) => null;`,
    truth: 'LOCAL',
  }),
  'ts-import-equals-member': (c) => ({
    imports: NS,
    decl: `import ${c.L} = N.${c.T};`,
    truth: 'T',
    langs: ['ts'],
    scopes: ['module'],
  }),
  'await-import-destructure': (c) => ({
    imports: '',
    decl: c.L === c.T ? `const { ${c.T} } = await import('./callee');` : `const { ${c.T}: ${c.L} } = await import('./callee');`,
    truth: 'T',
    scopes: ['fn'],
    async: true,
  }),
  'hook-result-destructure': (c) => ({
    imports: `import { ${c.T} as imp } from './callee';`,
    pre: `function useThing() { return { ${c.T}: imp }; }`,
    decl: c.L === c.T ? `const { ${c.T} } = useThing();` : `const { ${c.T}: ${c.L} } = useThing();`,
    truth: 'T',
    scopes: ['fn', 'outer'],
    contract: 'value returned by a same-file function (hook result)',
  }),
  'await-import-member': (c) => ({
    imports: '',
    decl: `const ${c.L} = (await import('./callee')).${c.T};`,
    truth: 'T',
    forms: ['call'],
    scopes: ['fn'],
    async: true,
  }),
  'await-import-default': (c) => ({
    imports: '',
    decl: `const ${c.L} = (await import('./dflt')).default;`,
    truth: 'DFLT',
    forms: ['call'],
    scopes: ['fn'],
    async: true,
    dflt: true,
  }),
  'ns-member-satisfies': (c) => ({ imports: NS, decl: `const ${c.L} = N.${c.T} satisfies typeof N.${c.T};`, truth: 'T', langs: ['ts'], forms: ['call'] }),
  'exported-ns-member': (c) => ({ imports: NS, decl: `export const ${c.L} = N.${c.T};`, truth: 'T', forms: ['call'], scopes: ['module'] }),
  'ident-of-reassigned-let': (c) => ({
    imports: NS,
    decl: `let base${ty(c.lang, ': any')} = N.${c.T}; if (c) { base = N.${c.ALT}; }\n  const ${c.L} = base;`,
    truth: 'SET',
    forms: ['call'],
    scopes: ['fn', 'outer'],
  }),
  'chain8': (c) => ({
    imports: `import { ${c.T} as imp } from './callee';`,
    decl: `const a1 = imp; const a2 = a1; const a3 = a2; const a4 = a3; const a5 = a4; const a6 = a5; const a7 = a6; const ${c.L} = a7;`,
    truth: 'T',
    forms: ['call'],
    scopes: ['fn'],
  }),
  'chain9': (c) => ({
    imports: `import { ${c.T} as imp } from './callee';`,
    decl: `const a1 = imp; const a2 = a1; const a3 = a2; const a4 = a3; const a5 = a4; const a6 = a5; const a7 = a6; const a8 = a7; const ${c.L} = a8;`,
    truth: 'T',
    forms: ['call'],
    scopes: ['fn'],
    contract: 'nine alias hops: one past the proposed eight-hop bound',
  }),
  'alias-of-param': (c) => ({
    imports: '',
    decl: `const ${c.L} = opts;`,
    truth: 'UNKNOWN',
    forms: ['call'],
    namings: ['trap', 'fresh'],
    scopes: ['fn', 'outer'],
  }),
  'catch-binding': (c) => ({
    imports: NS,
    decl: `const ${c.L} = N.${c.ALT};\n  try { opts(); } catch (${c.L}${ty(c.lang, ': any')}) {\n    ${FORMS[c.form].site(c.L)}\n  }`,
    noSite: true,
    truth: 'UNKNOWN',
    forms: ['call'],
    namings: ['trap', 'fresh'],
    scopes: ['fn'],
  }),
  'shadows-same-file-fn': (c) => ({
    imports: NS,
    pre: `export function ${c.L}(x${ty(c.lang, ': number')}) { return -x; }`,
    decl: `const ${c.L} = N.${c.T};`,
    truth: 'T',
    forms: ['call'],
    scopes: ['fn', 'outer'],
  }),
  'shadows-same-file-fn-props': (c) => ({
    imports: '',
    pre: `export function ${c.L}(x${ty(c.lang, ': number')}) { return -x; }`,
    decl: `const { ${c.L} } = opts;`,
    truth: 'UNKNOWN',
    forms: ['call'],
    scopes: ['fn', 'outer'],
  }),
  'shadows-same-file-fn-let': (c) => ({
    imports: NS,
    pre: `export function ${c.L}(x${ty(c.lang, ': number')}) { return -x; }`,
    decl: `let ${c.L}${ty(c.lang, ': any')} = N.${c.T}; if (c) { ${c.L} = N.${c.ALT}; }`,
    truth: 'SET',
    forms: ['call'],
    scopes: ['fn', 'outer'],
  }),
  'call-with-inline-fn': (c) => ({
    imports: '',
    pre: `function debounce(fn${ty(c.lang, ': any')}, ms${ty(c.lang, ': number')})${ty(c.lang, ': any')} { return fn; }`,
    decl: `const ${c.L} = debounce((x${ty(c.lang, ': any')}) => x, 100); // ANON`,
    truth: 'ANON',
    forms: ['call'],
    scopes: ['fn', 'outer'],
    contract: 'result of a call that takes an inline function: main binds the inline function (may-call ruling, 2026-09-27)',
  }),
  'rhs-shadowed-at-site': (c) => ({
    imports: `import { ${c.T} as imp } from './callee';\nimport * as N from './callee';`,
    pre: `const a0 = imp;`,
    decl: `const imp = N.${c.ALT};\n  const ${c.L} = a0;\n  void imp;`,
    truth: 'T',
    forms: ['call'],
    scopes: ['fn'],
  }),
  'ns-via-alias-hop': (c) => ({
    imports: NS,
    decl: `const M = N; const ${c.L} = M.${c.T};`,
    truth: 'T',
    forms: ['call'],
    contract: 'namespace object carried through an alias before the member access',
  }),
  'hook-result-two-keys': (c) => ({
    imports: `import { ${c.T} as imp, ${c.ALT} as imp2 } from './callee';`,
    pre: `function useThing() { return { first: imp2, second: imp }; }`,
    decl: `const { second: ${c.L} } = useThing();`,
    truth: 'T',
    forms: ['call'],
    scopes: ['fn', 'outer'],
    contract: 'value returned by a same-file function (hook result), second of two callable keys',
  }),
  'hook-result-two-slots': (c) => ({
    imports: `import { ${c.T} as imp, ${c.ALT} as imp2 } from './callee';`,
    pre: `function useThing() { return [imp2, imp]${ty(c.lang, ' as const')}; }`,
    decl: `const [first, ${c.L}] = useThing();\n  void first;`,
    truth: 'T',
    forms: ['call'],
    scopes: ['fn', 'outer'],
    contract: 'value returned by a same-file function (hook result), second of two callable slots',
  }),
  'ident-own-name-import': (c) => ({
    imports: `import { ${c.T} } from './callee';`,
    decl: `const ${c.L} = ${c.T};`,
    truth: 'T',
    forms: ['call', 'jsx'],
    namings: ['trap', 'fresh'],
  }),
  'ident-same-file-fn': (c) => ({
    imports: '',
    pre: `export function local1(x${ty(c.lang, ': any')}) { return x; }`,
    decl: `const ${c.L} = local1;`,
    truth: 'LOCAL1',
    forms: ['call'],
  }),
  'ident-rhs-is-outer-const': (c) => ({
    imports: `import { ${c.T} } from './callee';\nexport const keep = ${c.T};`,
    decl: `const ${c.T} = opts.cb;\n  function caller() {\n    const ${c.L} = ${c.T};\n    ${FORMS[c.form].site(c.L)}\n  }\n  return caller;`,
    noSite: true,
    truth: 'UNKNOWN',
    forms: ['call'],
    namings: ['trap', 'fresh'],
    scopes: ['fn'],
  }),
  'ident-rhs-is-catch-param': (c) => ({
    imports: `import { ${c.T} } from './callee';\nexport const keep = ${c.T};`,
    decl: `try { opts(); } catch (${c.T}${ty(c.lang, ': any')}) {\n    const ${c.L} = ${c.T};\n    ${FORMS[c.form].site(c.L)}\n  }`,
    noSite: true,
    truth: 'UNKNOWN',
    forms: ['call'],
    namings: ['trap', 'fresh'],
    scopes: ['fn'],
  }),
  'ident-alias-rebound-by-catch': (c) => ({
    imports: `import { ${c.T} } from './callee';`,
    decl: `const ${c.L} = ${c.T};\n  try { opts(${c.L}); } catch (${c.L}${ty(c.lang, ': any')}) {\n    ${FORMS[c.form].site(c.L)}\n  }`,
    noSite: true,
    truth: 'UNKNOWN',
    forms: ['call'],
    namings: ['trap', 'fresh'],
    scopes: ['fn'],
  }),
  'ident-inner-block-does-not-leak': (c) => ({
    imports: `import { ${c.T}, ${c.ALT} } from './callee';`,
    decl: `const ${c.L} = ${c.T};\n  if (c) {\n    const ${c.L} = ${c.ALT};\n    void ${c.L};\n  }`,
    truth: 'T',
    forms: ['call'],
    namings: ['trap', 'fresh'],
    scopes: ['fn'],
  }),
  'ns-member-exported-alias': (c) => ({
    imports: NS,
    decl: `const ${c.L} = N.renamed;`,
    truth: 'T',
    forms: ['call'],
    namings: ['trap', 'fresh'],
  }),
};

module.exports = { LOCAL_SHAPES };
